-- Existing-page keyword optimization for the public stone catalog.
-- Idempotent: safe to rerun after restoring a production backup.

BEGIN;

UPDATE categories
SET
  seo_title_fa = CASE slug
    WHEN 'travertine' THEN 'قیمت و خرید سنگ تراورتن | سنگ نما و اسلب | سنگ حسن'
    WHEN 'marble' THEN 'قیمت و خرید سنگ مرمریت | سنگ کف، پله و اسلب | سنگ حسن'
    WHEN 'granite' THEN 'قیمت و خرید سنگ گرانیت | اسلب، کف و پله | سنگ حسن'
    WHEN 'crystal' THEN 'قیمت و خرید سنگ چینی کریستال | اسلب و سنگ نما | سنگ حسن'
    WHEN 'onyx' THEN 'قیمت و خرید سنگ مرمر و اونیکس | انواع اسلب مرمر | سنگ حسن'
  END,
  seo_description_fa = CASE slug
    WHEN 'travertine' THEN 'قیمت و خرید انواع سنگ تراورتن برای نما، کف، پله و دیوارپوش؛ مقایسه تراورتن کرم و سفید، اسلب و تایل و استعلام بر اساس سورت و ابعاد.'
    WHEN 'marble' THEN 'قیمت و خرید انواع سنگ مرمریت برای کف، پله، دیوارپوش و کانتر؛ مشاهده اسلب و تایل مرمریت و استعلام دقیق بر اساس سورت، ابعاد و فرآوری.'
    WHEN 'granite' THEN 'قیمت و خرید سنگ گرانیت برای کف، پله، نما، محوطه و کانتر؛ بررسی اسلب و تایل گرانیت و استعلام قیمت بر اساس ابعاد و فرآوری.'
    WHEN 'crystal' THEN 'قیمت و خرید سنگ چینی یا کریستال برای اسلب، کف، پله، نما و دیوارپوش؛ بررسی محصولات موجود و استعلام بر اساس سورت، ابعاد و فرآوری.'
    WHEN 'onyx' THEN 'قیمت و خرید سنگ مرمر یا اونیکس برای اسلب، دیوار شاخص، نورپردازی از پشت و کانتر؛ مشاهده محصولات و استعلام پروژه‌ای.'
  END,
  intro_fa = CASE slug
    WHEN 'travertine' THEN 'سنگ تراورتن یکی از انتخاب‌های اصلی برای نمای ساختمان است و در رنگ‌های روشن، کرم، بژ، سفید، شکلاتی و نقره‌ای عرضه می‌شود. در این صفحه می‌توانید انواع تراورتن موجود را برای نما، دیوارپوش، کف و پله بررسی کنید و بین فرم‌های اسلب و تایل و فرآوری‌های مختلف مقایسه انجام دهید. قیمت سنگ تراورتن فقط از نام معدن یا محصول تعیین نمی‌شود؛ سورت، یکنواختی رنگ، میزان تخلخل، سلامت سنگ، جهت برش، ابعاد، ضخامت، نوع فرآوری و مقدار سفارش روی مبلغ نهایی اثر دارند. به همین دلیل کف قیمت محصولات منتخب به‌ازای هر مترمربع نمایش داده می‌شود، اما قیمت قطعی باید بر اساس بچ قابل‌تحویل و مشخصات پروژه تأیید شود. برای خرید سنگ تراورتن نما، علاوه بر رنگ و طرح، هماهنگی سورت در کل متراژ و انتخاب فرآوری متناسب با شرایط اجرا اهمیت دارد. در مقایسه چند تراورتن، تصاویر را در نور مشابه ببینید و موج‌دار یا بی‌موج بودن، تراکم حفره‌ها و کیفیت پرشدگی را کنار هم قرار دهید. برای نمای وسیع، تأمین کل متراژ از یک بچ و تفکیک صحیح سورت پیش از نصب اهمیت بیشتری از انتخاب یک پلاک نمونه بسیار روشن دارد. برای استعلام دقیق، نام تراورتن، ابعاد یا فرم عرضه، متراژ، ضخامت، فرآوری و شهر پروژه را ارسال کنید تا امکان تأمین و قیمت روز بررسی شود.'
    WHEN 'marble' THEN 'سنگ مرمریت در پروژه‌های داخلی برای کف، پله، دیوارپوش، لابی و کانتر کاربرد گسترده‌ای دارد و با زمینه‌های روشن، کرم، طوسی و مشکی در دسترس است. محصولات این صفحه به شکل اسلب یا تایل قابل بررسی هستند و انتخاب نهایی باید با توجه به محل اجرا و فرآوری انجام شود. قیمت سنگ مرمریت به معدن، سورت، میزان یکنواختی یا رگه‌داری، سلامت سطح، ابعاد، ضخامت، کیفیت برش و صیقل و مقدار سفارش وابسته است. بنابراین دو محموله با نام یکسان ممکن است قیمت متفاوتی داشته باشند. برای سنگ کف و پله، هماهنگی ضخامت، مقاومت سطح و نوع پرداخت اهمیت بیشتری دارد؛ برای اسلب مرمریت و دیوار شاخص نیز پیوستگی طرح، ابعاد سالم و امکان چیدمان سنگ‌ها باید بررسی شود. کف قیمت محصولات منتخب به‌ازای هر مترمربع در صفحه محصول نمایش داده می‌شود. هنگام مقایسه، کاربرد داخلی را دقیق مشخص کنید و نمونه‌ها را از نظر رگه، خطوط طبیعی، کیفیت رزین یا توری و یکنواختی صیقل بررسی کنید. برای کف بزرگ، چیدمان آزمایشی چند پلاک و برای دیوار اسلبی، بررسی جهت رگه و نقشه برش به برآورد دقیق‌تر پرت و نتیجه نهایی کمک می‌کند. برای خرید و استعلام دقیق، نام مرمریت، کاربرد، ابعاد، متراژ یا تعداد، ضخامت، فرآوری و شهر پروژه را مشخص کنید تا سورت و گزینه قابل‌تأمین متناسب با سفارش بررسی شود.'
    WHEN 'granite' THEN 'سنگ گرانیت به دلیل ساختار متراکم و تنوع فرآوری برای کف، پله، محوطه، نما و کانتر پروژه‌های ساختمانی بررسی می‌شود. در این صفحه انواع گرانیت روشن، مشکی و قرمز را در فرم اسلب و تایل می‌بینید و می‌توانید فرآوری مناسب فضای داخلی یا خارجی را انتخاب کنید. قیمت سنگ گرانیت به معدن و رنگ، سورت، اندازه دانه‌ها، سلامت سنگ، ابعاد، ضخامت و نوع پرداخت وابسته است. صیقلی، هوند، فلیم، چرمی و بوش‌همر ظاهر و عملکرد متفاوتی ایجاد می‌کنند و هزینه فرآوری یکسانی ندارند. برای سنگ پله و کف پرتردد، ضخامت و کیفیت لبه‌ها و سطح مهم است؛ برای اسلب گرانیت و کانتر نیز ابعاد سالم، طرح و کیفیت برش باید از روی محموله واقعی کنترل شود. قیمت‌های نمایش‌داده‌شده کف قیمت هر مترمربع محصولات منتخب هستند. برای محیط بیرونی، نمونه همان فرآوری نهایی را ببینید؛ فلیم یا بوش‌همر می‌تواند رنگ را نسبت به حالت صیقلی روشن‌تر نشان دهد. در سفارش پله و کف، هماهنگی ضخامت، کالیبراسیون قطعات و جزئیات لبه را همراه با تعداد و نقشه ابعاد اعلام کنید تا هزینه برش و پرت درست محاسبه شود. برای دریافت قیمت دقیق، نام گرانیت، ابعاد، مقدار، ضخامت، فرآوری و شهر پروژه را ارسال کنید تا امکان تأمین، بسته‌بندی و حمل متناسب با سفارش بررسی شود.'
    WHEN 'crystal' THEN 'سنگ چینی یا کریستال با زمینه‌های روشن و رگه‌های متنوع برای اسلب، کف، پله، دیوارپوش و در بعضی پروژه‌ها نما انتخاب می‌شود. محصولات این صفحه شامل چینی‌های ایرانی با طرح‌ها و سورت‌های متفاوت‌اند و باید بر اساس نمونه یا تصاویر بچ قابل‌تحویل مقایسه شوند. قیمت سنگ چینی فقط به نام محصول وابسته نیست؛ سفیدی یا رنگ زمینه، نظم رگه‌ها، سلامت اسلب، سورت، ابعاد، ضخامت، کیفیت صیقل یا هوند و مقدار سفارش روی قیمت اثر می‌گذارند. برای اسلب چینی، پیوستگی طرح و ابعاد سالم اهمیت زیادی دارد؛ برای کف و پله، ضخامت، نوع فرآوری و شرایط نصب نیز باید مشخص باشد. کف قیمت محصولات منتخب به‌ازای هر مترمربع نمایش داده می‌شود و قیمت نهایی بعد از تعیین جزئیات سفارش و موجودی قابل‌تحویل اعلام خواهد شد. در پروژه اسلبی، تصاویر کامل قطعات را کنار هم قرار دهید تا جهت رگه و امکان بوک‌مچ یا ادامه طرح مشخص شود. برای کف و پله نیز رنگ زمینه را در نور محل اجرا ببینید و پیش از سفارش درباره ضخامت، پرداخت سطح و روش نصب با مجری هماهنگ کنید. برای خرید سنگ چینی کریستال، نام سنگ، فرم اسلب یا تایل، ابعاد، متراژ، ضخامت، فرآوری و شهر پروژه را ارسال کنید تا گزینه مناسب پروژه بررسی شود.'
    WHEN 'onyx' THEN 'سنگ مرمر یا اونیکس به دلیل رگه‌ها، تنوع رنگ و قابلیت عبور نور بیشتر برای اسلب‌های دکوراتیو، دیوار شاخص، لابی، کانتر و نورپردازی از پشت بررسی می‌شود. هر قطعه مرمر طبیعی طرح متفاوتی دارد و انتخاب آن باید بر اساس تصاویر کامل اسلب‌ها، جهت رگه و چیدمان موردنظر انجام شود. قیمت سنگ مرمر به نوع و رنگ، کمیابی طرح، سلامت و ابعاد اسلب، ضخامت، کیفیت فرآوری، نیاز به توری یا رزین و مقدار سفارش وابسته است. برای پروژه‌های نورگذر، علاوه بر ظاهر سطح باید ضخامت، محل نور، فاصله منبع نور و ساختار نگهدارنده نیز در طراحی لحاظ شود. فرم عرضه رایج این محصولات اسلب و تایل است، اما موجودی و ابعاد هر طرح باید جداگانه تأیید شود. برای انتخاب چند اسلب، تصاویر را با شماره قطعه و ترتیب پیشنهادی چیدمان دریافت کنید و محل برش بازشوها یا اتصال‌ها را از قبل مشخص کنید. چیدمان نهایی را نیز پیش از برش تأیید کنید. در اجرای نور از پشت نیز دیدن نمونه روشن‌شده ضروری است، زیرا عبور نور و نمای رگه‌ها در همه قسمت‌های یک اسلب یکسان نیست. برای خرید یا استعلام قیمت اسلب مرمر، نام محصول، تصویر یا کد انتخابی، ابعاد، تعداد، فرآوری و شهر پروژه را ارسال کنید تا امکان تأمین و هماهنگی طرح بررسی شود.'
  END,
  updated_at = NOW()
WHERE slug IN ('travertine', 'marble', 'granite', 'crystal', 'onyx');

WITH product_content(slug, short_fa, overview_fa, applications_fa, selection_fa) AS (
  VALUES
    ('hassan-travertine',
      'برای بررسی قیمت و خرید تراورتن حسن، تصاویر سورت، ابعاد، فرآوری و کف قیمت هر مترمربع را ببینید. تراورتن کرم یا بژ حسن برای نما، دیوارپوش، کف، پله، اسلب و تایل قابل سفارش است.',
      'تراورتن حسن با نام تجاری Hassan Travertine و در بازار صادراتی با عبارت Hassan Beige Travertine معرفی می‌شود. زمینه کرم تا بژ و طرح طبیعی هر محموله می‌تواند با نمونه قبلی تفاوت داشته باشد؛ بنابراین انتخاب نهایی باید از روی تصاویر سورت یا بچ قابل‌تحویل انجام شود.',
      'تراورتن حسن برای نمای ساختمان، دیوارپوش داخلی و خارجی، کف و پله قابل بررسی است و می‌تواند به صورت اسلب یا تایل و با فرآوری‌هایی مانند صیقلی، هوند، چرمی، تیشه‌ای و بوش‌همر عرضه شود. فرآوری باید با محل اجرا و میزان لغزندگی یا تماس با آلودگی هماهنگ باشد.',
      'در خرید تراورتن حسن، تنها روشن یا بژ بودن زمینه را ملاک قرار ندهید. یکنواختی سورت در کل متراژ، میزان تخلخل، جهت برش، ضخامت، کیفیت پرشدگی و پرداخت لبه‌ها را نیز با سفارش پروژه تطبیق دهید.'),
    ('abbasabad-travertine',
      'قیمت و خرید تراورتن عباس‌آباد را بر اساس سورت، ابعاد، ضخامت و فرآوری بررسی کنید. این سنگ برای نما، دیوارپوش، کف و پله و در فرم اسلب یا تایل قابل سفارش است.',
      'تراورتن عباس‌آباد از نام‌های شناخته‌شده بازار سنگ نماست، اما همه سورت‌های آن ظاهر و قیمت یکسانی ندارند. میزان روشنی زمینه، نظم موج‌ها، سلامت سطح و یکدستی بار باید روی تصاویر همان محموله ارزیابی شود، نه فقط بر اساس نام سنگ.',
      'کاربرد اصلی تراورتن عباس‌آباد نمای ساختمان است و برای نماهای کلاسیک، رومی یا ترکیب‌های روشن بررسی می‌شود. بسته به ضخامت و فرآوری می‌توان آن را برای دیوارپوش، کف و پله نیز سفارش داد و فرم اسلب برای سطوح شاخص قابل بررسی است.',
      'برای مقایسه سورت‌های عباس‌آباد، نمونه‌ها را در نور مشابه ببینید و اختلاف رنگ، موج، حفره‌های پرشده و لب‌پریدگی را کنترل کنید. ابعاد و متراژ موردنیاز را پیش از انتخاب نهایی مشخص کنید تا کل سفارش از یک بچ هماهنگ تأمین شود.'),
    ('hajiabad-travertine',
      'برای قیمت و خرید تراورتن حاجی‌آباد، سورت واقعی، رنگ، ابعاد، ضخامت و فرآوری سفارش را مشخص کنید. این تراورتن برای نما، دیوارپوش، کف، پله، اسلب و تایل قابل بررسی است.',
      'تراورتن حاجی‌آباد در بازار با سورت‌ها و طیف‌های رنگی متفاوت عرضه می‌شود و همین تفاوت روی ظاهر و قیمت اثر می‌گذارد. تصاویر محصول برای شناخت اولیه مناسب‌اند، ولی تصمیم خرید باید بر اساس نمونه یا تصاویر بار آماده تحویل گرفته شود.',
      'حاجی‌آباد برای نمای بیرونی و داخلی، دیوارپوش، کف و پله قابل استفاده است و بسته به طرح پروژه به شکل تایل یا اسلب سفارش داده می‌شود. صیقلی برای نمایش بیشتر رنگ و هوند یا فرآوری‌های بافت‌دار برای کنترل بازتاب و لغزندگی قابل بررسی‌اند.',
      'هنگام خرید تراورتن حاجی‌آباد، رنگ زمینه، موج‌دار یا بی‌موج بودن برش، یکنواختی سورت و کیفیت پرشدگی را در کنار ضخامت و ابعاد کنترل کنید. برای پروژه بزرگ، امکان ادامه تأمین همان سورت باید پیش از ثبت سفارش سنجیده شود.'),
    ('darrehbokhari-travertine',
      'قیمت و خرید تراورتن دره‌بخاری بر اساس سورت، رنگ زمینه، ابعاد و فرآوری تعیین می‌شود. این محصول برای نما، دیوارپوش، کف و پله و به صورت اسلب یا تایل قابل بررسی است.',
      'تراورتن دره‌بخاری در پروژه‌های نمای روشن مطرح است، اما درجه روشنی و نظم طرح بین سورت‌ها و بچ‌های مختلف تغییر می‌کند. برای تشخیص دقیق، تصاویر نزدیک سطح و نمای کلی چند پلاک از بار قابل‌تحویل باید هم‌زمان بررسی شوند.',
      'دره‌بخاری بیشتر برای نمای ساختمان و دیوارهای بیرونی یا داخلی انتخاب می‌شود و در صورت انتخاب ضخامت و فرآوری مناسب برای کف و پله نیز قابل سفارش است. اسلب‌های سالم آن برای دیوار شاخص یا ورودی پروژه قابل بررسی‌اند.',
      'برای خرید این سنگ، میزان هماهنگی رنگ در کل متراژ، جهت موج، کیفیت رزین یا پرشدگی و سلامت گوشه‌ها را بررسی کنید. اگر نما سطح وسیعی دارد، برنامه چیدمان و تفکیک سورت پیش از نصب از اختلاف ناخواسته جلوگیری می‌کند.'),
    ('atashkooh-travertine',
      'برای استعلام قیمت و خرید تراورتن آتشکوه، سورت، ابعاد، متراژ، ضخامت و فرآوری را اعلام کنید. این تراورتن برای نما، دیوارپوش، کف و پله و فرم اسلب یا تایل قابل بررسی است.',
      'تراورتن آتشکوه در گروه تراورتن‌های روشن بازار قرار می‌گیرد، ولی رنگ، موج و یکدستی آن باید در هر محموله جداگانه کنترل شود. نام محصول به تنهایی کیفیت سورت را مشخص نمی‌کند و تصاویر بار واقعی مبنای مطمئن‌تری برای انتخاب هستند.',
      'کاربرد اصلی آتشکوه نمای ساختمان و سطوح معماری روشن است. در فرم تایل برای نما و دیوارپوش و در ابعاد بزرگ‌تر برای سطوح شاخص بررسی می‌شود؛ کف و پله نیز به ضخامت، فرآوری و شرایط اجرا وابسته‌اند.',
      'در مقایسه سورت‌ها به یکنواختی زمینه، تراکم حفره‌ها، کیفیت پرکننده، سلامت لبه و تلرانس ضخامت توجه کنید. برای نمای وسیع، تعداد پلاک‌های نمونه باید بیشتر باشد تا دامنه واقعی تغییرات سنگ پیش از خرید مشخص شود.'),
    ('abianeh-travertine',
      'قیمت و خرید تراورتن ابیانه را با توجه به سورت، رنگ، ابعاد، ضخامت و فرآوری بررسی کنید. امکان سفارش برای نما، دیوارپوش، کف، پله و در فرم اسلب یا تایل وجود دارد.',
      'تراورتن ابیانه با طیف‌ها و طرح‌های طبیعی متفاوت عرضه می‌شود و انتخاب آن باید متناسب با پالت رنگی پروژه انجام شود. اختلاف جزئی میان نمونه و سفارش طبیعی است، اما دامنه اختلاف باید با مشاهده چند قطعه از بچ مشخص شود.',
      'این سنگ برای نمای بیرونی و داخلی، دیوارپوش و جزئیات معماری قابل بررسی است. با انتخاب ضخامت و سطح مناسب می‌توان از آن برای کف و پله نیز استفاده کرد و اسلب آن برای دیوارهای شاخص یا ورودی کاربرد دارد.',
      'پیش از سفارش، موج یا بی‌موج بودن، رنگ غالب، میزان تخلخل و کیفیت فرآوری را مشخص کنید. هماهنگی سورت در متراژ پروژه و نوع بسته‌بندی برای حمل، به‌ویژه در ابعاد بزرگ، باید در استعلام نهایی لحاظ شود.'),
    ('silver-takab-travertine',
      'برای قیمت و خرید تراورتن تکاب نقره‌ای، تصاویر سورت، ابعاد، ضخامت و فرآوری را بررسی کنید. این سنگ برای نما، دیوارپوش، کف، پله، اسلب و تایل قابل سفارش است.',
      'تراورتن تکاب نقره‌ای با زمینه طوسی تا نقره‌ای شناخته می‌شود، اما شدت رنگ و الگوی موج در بارهای مختلف یکسان نیست. برای پروژه‌هایی که به سطح تیره یا خنثی نیاز دارند باید محدوده رنگ قابل‌قبول از ابتدا تعیین شود.',
      'تکاب برای نمای مدرن، ترکیب با سنگ‌های روشن، دیوارپوش و سطوح شاخص قابل بررسی است. فرآوری و ضخامت مناسب امکان استفاده در کف و پله را نیز فراهم می‌کند و فرم اسلب برای نمایش پیوستگی طرح مناسب‌تر است.',
      'در زمان خرید، تیرگی زمینه، وجود رگه‌های روشن، جهت برش و هماهنگی پلاک‌ها را ارزیابی کنید. سطح نهایی می‌تواند با صیقلی، هوند یا فرآوری بافت‌دار ظاهر متفاوتی داشته باشد؛ بنابراین نمونه فرآوری‌شده را مبنا قرار دهید.'),
    ('natanz-black-granite',
      'قیمت و خرید گرانیت مشکی نطنز را بر اساس سورت، ابعاد، ضخامت و فرآوری بررسی کنید. این گرانیت برای اسلب، تایل، کف، پله، نما، محوطه و کانتر قابل سفارش است.',
      'گرانیت مشکی نطنز برای پروژه‌هایی انتخاب می‌شود که به زمینه تیره و ظاهر منظم نیاز دارند. میزان تیرگی، تراکم دانه‌ها و یکنواختی سطح بین سورت‌ها تغییر می‌کند و باید روی چند قطعه از محموله واقعی بررسی شود.',
      'این گرانیت برای کف و پله، نما، محوطه، کانتر و دیوارپوش قابل بررسی است. اسلب صیقلی برای سطوح داخلی و کانتر و فرآوری‌هایی مانند فلیم یا چرمی برای فضاهای بیرونی و کنترل لغزندگی کاربرد متفاوتی دارند.',
      'برای سفارش گرانیت مشکی نطنز، یکنواختی رنگ، لکه‌ها یا دانه‌های روشن، کیفیت صیقل، ضخامت و پرداخت لبه را کنترل کنید. نوع فرآوری را پیش از قیمت‌گیری مشخص کنید، زیرا هزینه و ظاهر صیقلی، فلیم و چرمی یکسان نیست.'),
    ('nehbandan-granite',
      'برای قیمت و خرید گرانیت نهبندان، رنگ و دانه‌بندی سورت، ابعاد، ضخامت و فرآوری را اعلام کنید. این محصول برای اسلب، تایل، کف، پله، نما، محوطه و کانتر قابل بررسی است.',
      'گرانیت نهبندان با سورت‌ها و دانه‌بندی‌های متفاوت عرضه می‌شود و ظاهر نهایی هر بار باید جداگانه دیده شود. هماهنگی زمینه و پراکندگی دانه‌ها در پروژه‌های وسیع اهمیت بیشتری دارد و نباید فقط به تصویر یک پلاک تکی اتکا کرد.',
      'نهبندان برای کف پرتردد، پله، محوطه، نما و برخی کانترها قابل بررسی است. فرم تایل برای پوشش سطوح و اسلب برای ابعاد بزرگ‌تر مناسب است؛ فرآوری صیقلی، فلیم یا بوش‌همر نیز بر اساس فضای داخلی یا بیرونی انتخاب می‌شود.',
      'در خرید این گرانیت، دقت برش، تلرانس ضخامت، سلامت گوشه‌ها و یکنواختی فرآوری را کنترل کنید. اگر پروژه ترکیبی از کف و پله است، بهتر است رنگ و فرآوری هر دو بخش از یک سورت هماهنگ انتخاب شود.'),
    ('morvarid-mashhad-granite',
      'قیمت و خرید گرانیت مروارید مشهد به سورت، ابعاد، ضخامت و نوع فرآوری بستگی دارد. این گرانیت برای تایل و اسلب، کف، پله، نما، محوطه و کانتر قابل سفارش است.',
      'گرانیت مروارید مشهد با زمینه روشن و بافت دانه‌ای شناخته می‌شود، اما اندازه و تراکم دانه‌ها و یکنواختی رنگ در هر سورت تفاوت دارد. مشاهده چند قطعه کنار هم برای ارزیابی ظاهر سطح وسیع ضروری است.',
      'این محصول برای کف، پله، محوطه و نمای پروژه‌های مسکونی یا عمومی بررسی می‌شود و با فرآوری‌های مختلف می‌تواند سطح صیقلی یا بافت‌دار ایجاد کند. فرم اسلب نیز برای کانتر یا قطعات بزرگ قابل سفارش است.',
      'برای استعلام دقیق، کاربرد داخلی یا خارجی، ابعاد پلاک، ضخامت و فرآوری را مشخص کنید. در سفارش‌های پرتعداد، کنترل کالیبراسیون ضخامت و هماهنگی دانه‌بندی به کاهش اختلاف در نصب و بندها کمک می‌کند.'),
    ('khorramdareh-granite',
      'برای قیمت و خرید گرانیت خرمدره، سورت واقعی، ابعاد، ضخامت و فرآوری موردنیاز را مشخص کنید. این سنگ برای اسلب، تایل، کف، پله، نما، محوطه و کانتر قابل بررسی است.',
      'گرانیت خرمدره با زمینه و بافت دانه‌ای طبیعی عرضه می‌شود و اختلاف‌های جزئی میان پلاک‌ها بخشی از ماهیت سنگ است. با این حال دامنه رنگ و دانه‌بندی باید در سورت انتخابی با مقیاس پروژه هماهنگ باشد.',
      'خرمدره برای کف و پله، فضاهای بیرونی، محوطه و نما قابل بررسی است و در ابعاد اسلب برای سطوح بزرگ یا کانتر نیز سفارش داده می‌شود. نوع پرداخت باید بر اساس میزان رفت‌وآمد، رطوبت و ظاهر موردنظر انتخاب شود.',
      'پیش از خرید، سلامت سطح، لب‌پریدگی، تلرانس ضخامت و یکنواختی فرآوری را بررسی کنید. برای فضای بیرونی، نمونه همان فرآوری نهایی را ببینید؛ زیرا فلیم، بوش‌همر یا چرمی رنگ سنگ را نسبت به صیقلی تغییر می‌دهند.'),
    ('zanjan-bahare-granite',
      'قیمت و خرید گرانیت بهاره زنجان را با سورت، ابعاد، ضخامت و فرآوری مقایسه کنید. این محصول برای اسلب و تایل، کف، پله، نما، محوطه و کانتر قابل سفارش است.',
      'گرانیت بهاره زنجان دارای بافت دانه‌ای طبیعی است و برای انتخاب دقیق باید رنگ زمینه و پراکندگی دانه‌ها روی چند قطعه از بار دیده شود. عکس یک نمونه کوچک نمی‌تواند تغییرات کل متراژ را کامل نشان دهد.',
      'این گرانیت در کف، پله، محوطه و نمای ساختمان قابل بررسی است و با برش اسلب برای قطعات بزرگ یا کانتر نیز استفاده می‌شود. فرآوری صیقلی برای داخل و پرداخت‌های بافت‌دار برای محیط بیرونی گزینه‌های متفاوتی ایجاد می‌کنند.',
      'هنگام سفارش، ابعاد نهایی، تعداد یا متراژ، ضخامت و جزئیات لبه پله یا کانتر را اعلام کنید. هماهنگی سورت و ضخامت در قطعات مجاور برای نتیجه منظم نصب اهمیت زیادی دارد.'),
    ('nayin-red-granite',
      'برای قیمت و خرید گرانیت قرمز نائین، تصاویر سورت، ابعاد، ضخامت و فرآوری را بررسی کنید. این گرانیت برای اسلب، تایل، کف، پله، نما، محوطه و کانتر قابل سفارش است.',
      'گرانیت قرمز نائین برای ایجاد رنگ شاخص در پروژه انتخاب می‌شود و شدت قرمز، بافت دانه‌ای و لکه‌های طبیعی آن بین قطعات تغییر دارد. محدوده رنگ قابل‌قبول باید با پالت پروژه و تصاویر بار واقعی هماهنگ شود.',
      'این محصول برای کف و پله، محوطه، نما و جزئیات معماری قابل بررسی است. اسلب آن برای سطوح بزرگ‌تر یا کانترهای خاص و فرآوری‌های بافت‌دار برای محیط بیرونی کاربرد دارند.',
      'در خرید گرانیت قرمز، یکنواختی رنگ در متراژ، کیفیت برش و سطح، ضخامت و نوع پرداخت را کنترل کنید. ترکیب آن با سنگ‌های دیگر نیازمند نمونه کنارهم است تا تضاد رنگ در نور واقعی پروژه ارزیابی شود.'),
    ('dehbid-marble',
      'قیمت و خرید مرمریت دهبید را بر اساس سورت، رنگ، ابعاد، ضخامت و فرآوری بررسی کنید. این مرمریت برای اسلب، تایل، کف، پله، دیوارپوش و کانتر قابل سفارش است.',
      'مرمریت دهبید با سورت‌ها و زمینه‌های متفاوت عرضه می‌شود و نام دهبید به تنهایی ظاهر یا قیمت نهایی را مشخص نمی‌کند. روشنی زمینه، میزان رگه، یکدستی و سلامت سطح باید روی محموله قابل‌تحویل بررسی شود.',
      'دهبید برای کف داخلی، پله، لابی، دیوارپوش و کانتر قابل بررسی است. فرم اسلب برای سطوح بزرگ و نمایش طرح طبیعی و تایل برای پوشش منظم کف یا دیوار استفاده می‌شود؛ انتخاب فرآوری به میزان رفت‌وآمد وابسته است.',
      'در زمان خرید، سورت و دامنه تغییر رنگ، ضخامت، کیفیت صیقل و سلامت لبه‌ها را کنترل کنید. برای کف وسیع بهتر است چیدمان چند پلاک نمونه بررسی شود تا ظاهر کلی بندها و تغییرات طبیعی پیش از سفارش مشخص باشد.'),
    ('dehbid-black-marble',
      'برای قیمت و خرید مرمریت مشکی دهبید، سورت، رگه‌ها، ابعاد، ضخامت و فرآوری را مشخص کنید. این محصول برای اسلب، تایل، کف، پله، دیوارپوش و کانتر قابل بررسی است.',
      'مرمریت مشکی دهبید برای فضاهایی با پالت تیره و کنتراست بالا بررسی می‌شود. مقدار و جهت رگه‌ها و شدت رنگ مشکی در هر قطعه متفاوت است و انتخاب اسلب باید با دیدن تصویر کامل سطح انجام شود.',
      'این سنگ برای دیوار شاخص، کف داخلی، پله، لابی و کانتر قابل استفاده است. در اسلب‌های بزرگ، جهت رگه و امکان هماهنگی قطعات اهمیت بیشتری دارد و فرآوری صیقلی یا هوند جلوه متفاوتی ایجاد می‌کند.',
      'برای خرید، کیفیت صیقل، خطوط طبیعی، سلامت گوشه‌ها و نیاز احتمالی به تقویت پشت سنگ را بررسی کنید. در کنار متراژ، نقشه برش یا ابعاد قطعات را ارسال کنید تا پرت و جهت رگه در برآورد سفارش لحاظ شود.'),
    ('black-lashetor-marble',
      'قیمت و خرید مرمریت مشکی لاشتر به سورت، رگه، ابعاد، ضخامت و فرآوری وابسته است. این مرمریت برای اسلب، تایل، کف، پله، دیوارپوش و کانتر قابل سفارش است.',
      'مرمریت مشکی لاشتر با زمینه تیره و رگه‌های روشن شناخته می‌شود، اما تراکم و مسیر رگه در هر اسلب متفاوت است. برای پروژه‌های دکوراتیو باید تصاویر کامل اسلب‌ها و امکان هماهنگ‌کردن جهت طرح بررسی شود.',
      'لاشتر برای کف و پله داخلی، دیوار شاخص، لابی و کانتر قابل بررسی است. اسلب صیقلی کنتراست رگه‌ها را بیشتر نشان می‌دهد و هوند یا چرمی می‌تواند بازتاب سطح را کاهش دهد.',
      'هنگام سفارش، مقدار رگه موردپسند، ابعاد نهایی، جهت برش و فرآوری را مشخص کنید. خطوط طبیعی را با ترک یا شکست اشتباه نگیرید و سلامت ساختاری هر اسلب را از روی پشت و روی سنگ کنترل کنید.'),
    ('najafabad-black-marble',
      'برای قیمت و خرید مرمریت مشکی نجف‌آباد، سورت، طرح رگه، ابعاد و فرآوری را بررسی کنید. این سنگ برای اسلب، تایل، کف، پله، دیوارپوش و کانتر قابل سفارش است.',
      'مرمریت مشکی نجف‌آباد برای سطوح تیره و طراحی‌های دارای تضاد انتخاب می‌شود. رنگ زمینه و تعداد یا ضخامت رگه‌ها میان سورت‌ها تغییر می‌کند و باید با تصاویر بار واقعی و نور مشابه پروژه سنجیده شود.',
      'کاربردهای آن شامل کف و پله داخلی، دیوار شاخص، لابی و کانتر است. فرم اسلب برای نمایش پیوستگی رگه‌ها و تایل برای چیدمان منظم مناسب است؛ نوع پرداخت نیز بر تیرگی و بازتاب سطح اثر می‌گذارد.',
      'در خرید، هماهنگی رنگ میان قطعات، سلامت لبه، کیفیت صیقل و ابعاد مفید اسلب را بررسی کنید. اگر پروژه به چند اسلب نیاز دارد، ترتیب چیدمان و جهت رگه‌ها پیش از برش مشخص شود.'),
    ('golden-black-marble',
      'قیمت و خرید مرمریت گلدن بلک را با توجه به سورت، رگه‌های طلایی، ابعاد و فرآوری بررسی کنید. این محصول برای اسلب، تایل، کف، پله، دیوارپوش و کانتر قابل سفارش است.',
      'مرمریت گلدن بلک ترکیبی از زمینه تیره و رگه‌های روشن یا طلایی دارد و هر اسلب الگوی منحصربه‌فردی نشان می‌دهد. میزان رگه و کنتراست باید متناسب با فضای پروژه و از روی تصاویر کامل سنگ انتخاب شود.',
      'این مرمریت برای دیوار شاخص، لابی، کف و پله داخلی و کانترهای دکوراتیو قابل بررسی است. اسلب صیقلی برای نمایش رگه‌ها و پرداخت هوند برای ظاهر آرام‌تر گزینه‌های متفاوتی فراهم می‌کنند.',
