      'برای سفارش، ابعاد مفید اسلب، سلامت رگه‌ها، ضخامت، کیفیت صیقل و ترتیب قطعات را بررسی کنید. ارسال نقشه یا ابعاد دقیق سطح به انتخاب اسلب و کاهش پرت کمک می‌کند.')
),
product_category AS (
  SELECT p.id, p.slug, p.title_fa, p.price, c.slug AS category_slug
  FROM products p
  JOIN categories c ON c.id = p.main_category_id
)
UPDATE products p
SET
  short_description_html_fa = '<p>' || pc.short_fa || '</p>',
  description_html_fa =
    '<p>' || pc.overview_fa || '</p>' ||
    '<h2>کاربردهای ' || p.title_fa || '</h2><p>' || pc.applications_fa || '</p>' ||
    '<h2>قیمت ' || p.title_fa || '</h2><p>قیمت ' || p.title_fa || ' به سورت، ابعاد، ضخامت، نوع فرآوری، مقدار سفارش و شرایط حمل بستگی دارد. عدد نمایش‌داده‌شده در این صفحه کف قیمت هر مترمربع است و قیمت نهایی پس از بررسی بچ قابل‌تحویل و مشخصات سفارش تأیید می‌شود. مقایسه قیمت بدون یکسان‌کردن این مشخصات می‌تواند نتیجه نادرستی ایجاد کند.</p>' ||
    '<h2>راهنمای خرید ' || p.title_fa || '</h2><p>' || pc.selection_fa || '</p>' ||
    '<p>پیش از نهایی‌کردن خرید، تصاویر بار قابل‌تحویل و مشخصات ثبت‌شده در پیش‌فاکتور را با نیاز پروژه تطبیق دهید و درباره دامنه طبیعی تغییر رنگ و طرح، تلرانس ابعاد و شرایط بسته‌بندی توافق کنید.</p>' ||
    '<p>برای استعلام دقیق، نام سنگ، ابعاد، متراژ یا تعداد، ضخامت، نوع فرآوری و شهر پروژه را ارسال کنید. محصولات هم‌گروه را در <a href="/fa/products/' || product_category.category_slug || '">صفحه ' ||
      CASE product_category.category_slug WHEN 'crystal' THEN 'سنگ چینی کریستال' WHEN 'marble' THEN 'سنگ مرمریت' WHEN 'granite' THEN 'سنگ گرانیت' WHEN 'travertine' THEN 'سنگ تراورتن' ELSE 'محصولات سنگ' END ||
    '</a> مقایسه کنید و برای شناخت عوامل انتخاب، <a href="/fa/blogs/' ||
      CASE product_category.category_slug WHEN 'crystal' THEN 'everything-about-crystal-stone' WHEN 'marble' THEN 'everything-about-marble-stone' WHEN 'granite' THEN 'everything-about-granite-stone' WHEN 'travertine' THEN 'everything-about-travertine-stone' ELSE 'why-stone-prices-are-different' END ||
    '">راهنمای مرتبط سنگ حسن</a> را بخوانید.</p>',
  price_html = '<p><strong>کف قیمت ' || p.title_fa || ':</strong> از ' || TRIM(TO_CHAR(p.price, 'FM999,999,999')) || ' تومان به‌ازای هر مترمربع. قیمت نهایی پس از تعیین سورت و مشخصات سفارش اعلام می‌شود.</p>',
  updated_at = NOW()
FROM product_content pc
JOIN product_category ON product_category.slug = pc.slug
WHERE p.id = product_category.id;

UPDATE products
SET
  title_en = 'Hassan Beige Travertine',
  aliases = ARRAY(SELECT DISTINCT value FROM UNNEST(COALESCE(aliases, '{}'::text[]) || ARRAY['Hassan Travertine', 'Iranian Beige Travertine', 'Cream Travertine from Iran']) AS alias(value)),
  short_description_html_en = '<p>Hassan Beige Travertine is an Iranian beige-to-cream natural stone available as slabs and tiles for facades, wall cladding, flooring, and stairs. Review the current gallery, finishes, and starting price per square metre before requesting a project quote.</p>',
  description_html_en = '<p>Hassan Beige Travertine, also known as Hassan Travertine, is an Iranian beige travertine offered for architectural and project supply. Its cream-to-beige background and natural movement can vary between production batches, so the final selection should be based on current slab or tile images rather than a single reference sample.</p><h2>Hassan Beige Travertine slabs and tiles</h2><p>The material can be supplied as beige travertine slabs or tiles and considered for exterior facades, interior and exterior wall cladding, flooring, and stairs. Available finishes include polished, honed, leathered, chiseled, grooved, and other textured options shown in the product specifications. The selected finish should match the installation area, slip requirements, maintenance expectations, and intended visual result.</p><h2>Beige Travertine price and project supply</h2><p>The displayed amount is the starting price per square metre. The final Hassan Beige Travertine price depends on grade, dimensions, thickness, finish, quantity, packing, and destination. Before ordering, compare the color range, vein direction, filling quality, edge condition, and consistency across the required quantity.</p><p>For an accurate supply quote, send the stone name, slab or tile dimensions, required quantity, thickness, finish, and project city or destination. SangeHassan will review the suitable production batch and project sourcing options.</p>',
  updated_at = NOW()
WHERE slug = 'hassan-travertine';

-- Add applications and supply forms to existing natural-stone products only.
WITH category_rules(category_slug, taxonomy, term_key) AS (
  VALUES
    ('travertine', 'use_case_form', 'slab'), ('travertine', 'use_case_form', 'tile'),
    ('travertine', 'use_case_application', 'facade'), ('travertine', 'use_case_application', 'wall_cladding'),
    ('travertine', 'use_case_application', 'flooring'), ('travertine', 'use_case_application', 'stairs'),
    ('granite', 'use_case_form', 'slab'), ('granite', 'use_case_form', 'tile'),
    ('granite', 'use_case_application', 'flooring'), ('granite', 'use_case_application', 'stairs'),
    ('granite', 'use_case_application', 'facade'), ('granite', 'use_case_application', 'landscaping'),
    ('granite', 'use_case_application', 'countertops'),
    ('marble', 'use_case_form', 'slab'), ('marble', 'use_case_form', 'tile'),
    ('marble', 'use_case_application', 'flooring'), ('marble', 'use_case_application', 'stairs'),
    ('marble', 'use_case_application', 'wall_cladding'), ('marble', 'use_case_application', 'countertops'),
    ('crystal', 'use_case_form', 'slab'), ('crystal', 'use_case_form', 'tile'),
    ('crystal', 'use_case_application', 'flooring'), ('crystal', 'use_case_application', 'stairs'),
    ('crystal', 'use_case_application', 'wall_cladding'), ('crystal', 'use_case_application', 'facade'),
    ('onyx', 'use_case_form', 'slab'), ('onyx', 'use_case_form', 'tile'),
    ('onyx', 'use_case_application', 'wall_cladding'), ('onyx', 'use_case_application', 'feature_wall'),
    ('onyx', 'use_case_application', 'backlit'), ('onyx', 'use_case_application', 'countertops'),
    ('basalt', 'use_case_form', 'slab'), ('basalt', 'use_case_form', 'tile'),
    ('basalt', 'use_case_application', 'flooring'), ('basalt', 'use_case_application', 'stairs'),
    ('basalt', 'use_case_application', 'facade'), ('basalt', 'use_case_application', 'landscaping'),
    ('sand-stone', 'use_case_form', 'slab'), ('sand-stone', 'use_case_form', 'tile'),
    ('sand-stone', 'use_case_application', 'facade'), ('sand-stone', 'use_case_application', 'wall_cladding'),
    ('sand-stone', 'use_case_application', 'landscaping')
),
product_categories AS (
  SELECT p.id AS product_id, c.slug AS category_slug
  FROM products p
  JOIN categories c ON c.id = p.main_category_id
  WHERE p.is_active = TRUE
  UNION
  SELECT p.id, c.slug
  FROM products p
  JOIN product_categories pc ON pc.product_id = p.id
  JOIN categories c ON c.id = pc.category_id
  WHERE p.is_active = TRUE
),
direct_candidates AS (
  SELECT DISTINCT pc.product_id, r.taxonomy, r.term_key
  FROM product_categories pc
  JOIN category_rules r ON r.category_slug = pc.category_slug
),
imported_stone_types AS (
  SELECT DISTINCT p.id AS product_id, type_term.term_key AS category_slug
  FROM products p
  JOIN categories c ON c.id = p.main_category_id AND c.slug = 'imported-stones'
  JOIN product_term_links type_link ON type_link.product_id = p.id
  JOIN product_terms type_term ON type_term.id = type_link.term_id AND type_term.taxonomy = 'stone_type'
  WHERE p.is_active = TRUE
),
imported_candidates AS (
  SELECT DISTINCT i.product_id, r.taxonomy, r.term_key
  FROM imported_stone_types i
  JOIN category_rules r ON r.category_slug = i.category_slug
),
all_candidates AS (
  SELECT * FROM direct_candidates
  UNION
  SELECT * FROM imported_candidates
)
INSERT INTO product_term_links (product_id, term_id)
SELECT candidate.product_id, term.id
FROM all_candidates candidate
JOIN product_terms term
  ON term.taxonomy = candidate.taxonomy
 AND term.term_key = candidate.term_key
 AND term.is_active = TRUE
ON CONFLICT DO NOTHING;

