  VALUES
    ('everything-about-travertine-stone', '<section data-seo-links="existing-products"><h2>بررسی محصولات و قیمت تراورتن</h2><p>برای مقایسه گزینه‌های موجود به <a href="/fa/products/travertine">صفحه خرید و قیمت سنگ تراورتن</a> بروید و محصولات <a href="/fa/products/hassan-travertine">تراورتن حسن</a>، <a href="/fa/products/abbasabad-travertine">تراورتن عباس‌آباد</a> و <a href="/fa/products/hajiabad-travertine">تراورتن حاجی‌آباد</a> را بررسی کنید.</p></section>'),
    ('travertine-stone-price-factors', '<section data-seo-links="existing-products"><h2>استعلام قیمت تراورتن‌های موجود</h2><p>کف قیمت محصولات منتخب در <a href="/fa/products/travertine">صفحه قیمت سنگ تراورتن</a> نمایش داده می‌شود. برای مقایسه سورت و تصاویر، صفحات <a href="/fa/products/hassan-travertine">تراورتن حسن</a>، <a href="/fa/products/abbasabad-travertine">عباس‌آباد</a>، <a href="/fa/products/hajiabad-travertine">حاجی‌آباد</a>، <a href="/fa/products/darrehbokhari-travertine">دره‌بخاری</a> و <a href="/fa/products/atashkooh-travertine">آتشکوه</a> را ببینید.</p></section>'),
    ('best-travertine-stone-for-building-facade', '<section data-seo-links="existing-products"><h2>تراورتن‌های قابل بررسی برای نما</h2><p>در میان محصولات موجود می‌توانید <a href="/fa/products/hassan-travertine">تراورتن حسن</a>، <a href="/fa/products/abbasabad-travertine">عباس‌آباد</a>، <a href="/fa/products/hajiabad-travertine">حاجی‌آباد</a> و <a href="/fa/products/atashkooh-travertine">آتشکوه</a> را مقایسه کنید. فهرست کامل در <a href="/fa/products/travertine">دسته سنگ تراورتن نما</a> قرار دارد.</p></section>'),
    ('is-travertine-suitable-for-flooring', '<section data-seo-links="existing-products"><h2>بررسی تراورتن برای کف و پله</h2><p>فرم عرضه و فرآوری محصولات را در <a href="/fa/products/travertine">دسته تراورتن</a> مقایسه کنید. صفحات <a href="/fa/products/hassan-travertine">تراورتن حسن</a>، <a href="/fa/products/silver-takab-travertine">تراورتن تکاب</a> و <a href="/fa/products/abianeh-travertine">تراورتن ابیانه</a> تصاویر و مشخصات قابل بررسی دارند.</p></section>'),
    ('everything-about-granite-stone', '<section data-seo-links="existing-products"><h2>بررسی قیمت و محصولات گرانیت</h2><p>برای مقایسه محصولات موجود به <a href="/fa/products/granite">صفحه خرید و قیمت سنگ گرانیت</a> بروید و <a href="/fa/products/natanz-black-granite">گرانیت مشکی نطنز</a>، <a href="/fa/products/nehbandan-granite">گرانیت نهبندان</a> و <a href="/fa/products/morvarid-mashhad-granite">گرانیت مروارید مشهد</a> را بررسی کنید.</p></section>'),
    ('everything-about-marble-stone', '<section data-seo-links="existing-products"><h2>بررسی قیمت و محصولات مرمریت</h2><p>محصولات موجود در <a href="/fa/products/marble">صفحه خرید و قیمت سنگ مرمریت</a> قابل مقایسه‌اند. برای مشاهده تصاویر و مشخصات، صفحات <a href="/fa/products/dehbid-marble">مرمریت دهبید</a>، <a href="/fa/products/black-lashetor-marble">مرمریت مشکی لاشتر</a> و <a href="/fa/products/gandomak-marble">مرمریت گندمک</a> را ببینید.</p></section>'),
    ('everything-about-crystal-stone', '<section data-seo-links="existing-products"><h2>بررسی اسلب و قیمت سنگ چینی</h2><p>برای مقایسه محصولات به <a href="/fa/products/crystal">صفحه خرید و قیمت سنگ چینی کریستال</a> بروید و <a href="/fa/products/aligoodarz-crystal">چینی الیگودرز</a>، <a href="/fa/products/laybid-crystal">چینی لایبید</a> و <a href="/fa/products/sirjan-crystal">چینی سیرجان</a> را بررسی کنید.</p></section>'),
    ('why-stone-prices-are-different', '<section data-seo-links="existing-products"><h2>مشاهده کف قیمت محصولات موجود</h2><p>برای مشاهده محصولات قیمت‌دار و مقایسه دسته‌ها به <a href="/fa/products">صفحه خرید و قیمت سنگ ساختمانی</a> بروید. قیمت نهایی هر سنگ پس از تعیین سورت، ابعاد، مقدار، فرآوری و شهر پروژه تأیید می‌شود.</p></section>')
)
UPDATE blog_translations translation
SET content_html = translation.content_html || related_links.links_html,
    updated_at = NOW()
FROM related_links
WHERE translation.locale = 'fa'
  AND translation.slug = related_links.slug
  AND translation.translation_status = 'published'
  AND POSITION('data-seo-links="existing-products"' IN translation.content_html) = 0;

COMMIT;
